grid=[[8]*27 for _ in range(3)]; marks=[[4,13,18,24],[1,2,8,11,19],[11,20,23]]
for r, cols in enumerate(marks):
    for c in cols: grid[r][c]=5
    for a,b in zip(cols,cols[1:]):
        for c in range(a+1,b): grid[r][c]=3
# vertical same-column marker pairs
for c in range(27):
    rs=[r for r in range(3) if grid[r][c]==5]
    for a,b in zip(rs,rs[1:]):
        for r in range(a+1,b): grid[r][c]=3
grid
